<script setup lang="ts">
import{AlertCircle,Check,Crown,LoaderCircle}from"lucide-vue-next";
definePageMeta({layout:"dashboard",middleware:"auth"});
const{tr,formatDate,formatNumber}=useAppPreferences(),route=useRoute();
const{data,status,refresh}=await useFetch<any>("/api/subscription");
const busy=ref(""),error=ref(""),provider=ref("zarinpal");
const days=computed(()=>data.value?.subscription?.endsAt?Math.max(0,Math.ceil((new Date(data.value.subscription.endsAt).getTime()-Date.now())/86400000)):0);
const unavailable=(plan:any)=>data.value?.subscription?.planId===plan.id||(!Number(plan.price)&&(data.value?.freeUsed||Number(data.value?.subscription?.plan?.price)>0));
async function buy(plan:any){if(unavailable(plan))return;busy.value=plan.id;error.value="";try{const r=await $fetch<any>("/api/payments/create",{method:"POST",body:{planId:plan.id,provider:provider.value}});if(r.activated){await refresh();await navigateTo("/dashboard/subscription?payment=success");return}await navigateTo(r.redirectUrl,{external:r.redirectUrl.startsWith("http")})}catch(e:any){error.value=e.data?.statusMessage||tr("شروع پرداخت انجام نشد؛ دوباره تلاش کنید.","Could not start payment. Please retry.")}finally{busy.value=""}}
</script>
<template><div><PageHeader :title="tr('اشتراک و پرداخت','Subscription & billing')" :description="tr('پلن فعال، محدودیت‌ها و سوابق پرداخت حساب.','Your active plan, limits, and payment history.')"/><div v-if="route.query.payment==='success'" class="mb-4 rounded-xl bg-emerald-50 p-4 font-bold text-emerald-700">{{tr('اشتراک با موفقیت فعال شد.','Subscription activated successfully.')}}</div><div v-if="error" class="mb-4 flex gap-2 rounded-xl bg-red-50 p-4 text-red-700"><AlertCircle :size="20"/>{{error}}</div><div v-if="status==='pending'" class="surface grid h-60 place-items-center"><LoaderCircle class="animate-spin"/></div><template v-else><section v-if="data?.subscription" class="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><article class="relative overflow-hidden rounded-3xl bg-gradient-to-br from-violet-600 to-indigo-800 p-7 text-white shadow-xl"><Crown class="absolute -end-8 -top-8 size-40 text-white/5"/><span class="badge bg-white/10 text-violet-100">{{tr('فعال','Active')}}</span><h2 class="mt-5 text-2xl font-black">{{data.subscription.plan.name}}</h2><p class="mt-2 text-sm text-violet-200">{{formatNumber(days)}} {{tr('روز باقی‌مانده','days remaining')}}</p><b class="mt-8 block text-3xl">{{formatNumber(data.subscription.plan.price)}} {{tr('تومان','IRR')}}</b></article><article class="surface p-6"><h2 class="font-black">{{tr('محدودیت‌های پلن','Plan limits')}}</h2><ul class="mt-5 space-y-4"><li v-for="x in [`${formatNumber(data.subscription.plan.maxWhatsAppConnections)} WhatsApp`,`${formatNumber(data.subscription.plan.maxMessages)} ${tr('پیام','messages')}`,`${formatNumber(data.subscription.plan.maxAIRequests)} AI`,`${formatNumber(data.subscription.plan.maxWebhooks)} Webhook` ]" :key="x" class="flex items-center gap-3 text-sm"><span class="grid size-6 place-items-center rounded-full bg-brand-50 text-brand-600"><Check :size="14"/></span>{{x}}</li></ul></article></section><section class="surface mt-5 flex flex-wrap items-center gap-3 p-4"><b class="text-sm">{{tr('درگاه پرداخت','Payment gateway')}}</b><select v-model="provider" class="input max-w-xs"><option value="zarinpal">{{tr('زرین‌پال آزمایشی','Zarinpal sandbox')}}</option><option value="mock">{{tr('درگاه داخلی آزمایشی','Internal test gateway')}}</option></select></section><section class="mt-5 grid gap-4 md:grid-cols-3"><article v-for="plan in data?.plans" :key="plan.id" class="surface p-6" :class="data?.subscription?.planId===plan.id?'border-brand-500 ring-2 ring-brand-500/10':''"><h3 class="font-black">{{plan.name}}</h3><b class="mt-3 block text-xl text-brand-600">{{formatNumber(plan.price)}} {{tr('تومان','IRR')}}</b><p class="muted mt-2 text-xs">{{formatNumber(plan.durationDays)}} {{tr('روز','days')}}</p><ul class="my-5 space-y-2 text-sm"><li v-for="f in plan.features" :key="f">✓ {{f}}</li></ul><button class="btn w-full" :class="unavailable(plan)?'btn-secondary':'btn-primary'" :disabled="busy===plan.id||unavailable(plan)" @click="buy(plan)"><LoaderCircle v-if="busy===plan.id" class="animate-spin" :size="17"/>{{data?.subscription?.planId===plan.id?tr('پلن فعلی','Current plan'):!Number(plan.price)&&data?.freeUsed?tr('قبلاً استفاده شده','Already used'):Number(plan.price)?tr('خرید پلن','Buy plan'):tr('فعال‌سازی رایگان','Activate free')}}</button></article></section><section class="surface mt-5 overflow-hidden"><header class="border-b p-5"><h2 class="font-black">{{tr('تاریخچه سفارش‌ها','Order history')}}</h2></header><div v-if="!data?.orders.length" class="muted p-8 text-center">{{tr('سفارشی ثبت نشده است.','No orders yet.')}}</div><div v-for="order in data?.orders" :key="order.id" class="grid gap-3 border-b p-5 sm:grid-cols-4"><code>{{order.id.slice(-10)}}</code><span>{{formatDate(order.createdAt,{dateStyle:'medium'})}}</span><b>{{formatNumber(order.amount)}} {{tr('تومان','IRR')}}</b><span class="badge w-fit" :class="order.status==='PAID'?'bg-emerald-50 text-emerald-600':'bg-amber-50 text-amber-600'">{{order.status}}</span></div></section></template></div></template>
